import { createTeamsFromParticipantAttributes } from '../../../mutate/participants/createTeamsFromAttributes.mjs';
import { getParticipantId } from '../../../functions/global/extractors.mjs';
import { generateParticipants } from './generateParticipants.mjs';
import { getParticipantsCount } from './getParticipantsCount.mjs';
import { addParticipantsRecorded } from './recordedWrites.mjs';
import { generateRange } from '../../../tools/arrays.mjs';
import { INDIVIDUAL, TEAM } from '../../../constants/participantConstants.mjs';
import { FEMALE, MALE } from '../../../constants/genderConstants.mjs';
import { COMPETITOR } from '../../../constants/participantRoleValues.mjs';
import { genParticipantId } from './genParticipantId.mjs';
import { SUCCESS } from '../../../constants/resultConstants.mjs';

function addTournamentParticipants({ participantsProfile, tournamentRecord, eventProfiles, drawProfiles, startDate, random, uuids, }) {
    if (participantsProfile?.participantsCount === 0)
        return { addedCount: 0, ...SUCCESS };
    const { participantsCount, participantType, largestTeamDraw, largestTeamSize, gendersCount, teamGenders } = getParticipantsCount({
        participantsProfile,
        eventProfiles,
        drawProfiles,
    });
    const teamKey = participantsProfile?.teamKey;
    const idPool = participantsProfile?.uuids ?? uuids;
    const generated = generateParticipants({
        consideredDate: startDate,
        consideredEndDate: tournamentRecord?.endDate,
        ...participantsProfile,
        participantsCount,
        participantType,
        uuids: idPool,
        gendersCount,
        random,
    });
    if (generated.error)
        return generated;
    const participants = generated.participants;
    let addedCount = 0;
    let result = addParticipantsRecorded({ tournamentRecord, participants });
    if (result.error)
        return result;
    addedCount += result.addedCount;
    if (teamKey) {
        const built = createTeamsFromParticipantAttributes({
            tournamentRecord,
            ...teamKey,
            addParticipants: false,
        });
        if (built.error)
            return built;
        const teams = 'newParticipants' in built ? built.newParticipants : [];
        const result = addParticipantsRecorded({ tournamentRecord, participants: teams });
        if (result.error)
            return result;
    }
    const individuals = participants.filter(({ participantType }) => participantType === INDIVIDUAL);
    const ofSex = (sex) => individuals.filter(({ person }) => person?.sex === sex).map(getParticipantId);
    const queues = { [MALE]: ofSex(MALE), [FEMALE]: ofSex(FEMALE) };
    const dealt = new Set();
    const take = (ids, count) => {
        const taken = ids.filter((id) => !dealt.has(id)).slice(0, count);
        taken.forEach((id) => dealt.add(id));
        return taken;
    };
    const teamMembers = generateRange(0, largestTeamDraw).map(() => [
        ...take(queues[MALE], teamGenders[MALE]),
        ...take(queues[FEMALE], teamGenders[FEMALE]),
    ]);
    const everyone = individuals.map(getParticipantId);
    teamMembers.forEach((members) => members.push(...take(everyone, largestTeamSize - members.length)));
    const idPrefix = participantsProfile?.idPrefix ? `${TEAM}-${participantsProfile.idPrefix}` : undefined;
    const teamParticipants = generateRange(0, largestTeamDraw).map((teamIndex) => {
        const individualParticipantIds = teamMembers[teamIndex];
        const participantId = genParticipantId({
            index: teamIndex,
            participantType,
            uuids: idPool,
            idPrefix,
            random,
        });
        return {
            participantName: `Team ${teamIndex + 1}`,
            participantRole: COMPETITOR,
            individualParticipantIds,
            participantType: TEAM,
            participantId,
        };
    });
    result = addParticipantsRecorded({
        participants: teamParticipants,
        tournamentRecord,
    });
    if (result.error)
        return result;
    addedCount += result.addedCount;
    return { addedCount, ...SUCCESS };
}

export { addTournamentParticipants };
